    /// <c>to-rgba</c> expression (Color): Returns a four-element array containing the input color's red, green, blue, and alpha components, in that order.
    /// </summary>
    /// <remarks>
    /// Supported by Mapbox GL JS and MapLibre GL JS.
    /// </remarks>
    public static Expression ToRgba(params object?[] args) => Expression.Create("to-rgba", args);

    /// <summary>
    /// <c>typeof</c> expression (Types): Returns a string describing the type of the given value.
    /// </summary>
    /// <remarks>
    /// Supported by Mapbox GL JS and MapLibre GL JS.
    /// </remarks>
    public static Expression TypeOf(params object?[] args) => Expression.Create("typeof", args);

    /// <summary>
    /// <c>upcase</c> expression (String): Returns the input string converted to uppercase. Follows the Unicode Default Case Conversion algorithm and the locale-insensitive case mappings in the Unicode Character Database.
    /// </summary>
    /// <remarks>
    /// Supported by Mapbox GL JS and MapLibre GL JS.
    /// </remarks>
    public static Expression Upcase(params object?[] args) => Expression.Create("upcase", args);

    /// <summary>
    /// <c>within</c> expression (Decision): Returns <c>true</c> if the evaluated feature is fully contained inside a boundary of the input geometry, <c>false</c> otherwise. The input value can be a valid GeoJSON of type <c>Polygon</c>, <c>MultiPolygon</c>, <c>Feature</c>, or <c>FeatureCollection</c>. Supported features for evaluation:
    /// - <c>Point</c>: Returns <c>false</c> if a point is on the boundary or falls outside the boundary.
    /// - <c>LineString</c>: Returns <c>false</c> if any part of a line falls outside the boundary, the line intersects the boundary, or a line's endpoint is on the boundary.
    /// </summary>
    /// <remarks>
    /// Supported by Mapbox GL JS and MapLibre GL JS.
    /// </remarks>
    public static Expression Within(params object?[] args) => Expression.Create("within", args);

    /// <summary>
    /// <c>worldview</c> expression (Lookup): Returns the current worldview being used.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// </remarks>
    public static Expression Worldview(params object?[] args) => Expression.Create("worldview", args);

}
